-- Durable per-client rate limiting for the public Fresh Research endpoint.
-- The identifier is an HMAC digest generated by the server; raw IP addresses are never stored.
create schema if not exists fresh_internal;
revoke all on schema fresh_internal from public, anon, authenticated, service_role;

create table if not exists fresh_internal.research_rate_limits (
  bucket_hash text primary key check (bucket_hash ~ '^[a-f0-9]{64}$'),
  window_started_at timestamptz not null,
  request_count integer not null check (request_count > 0),
  updated_at timestamptz not null
);

create index if not exists research_rate_limits_updated_at_idx
  on fresh_internal.research_rate_limits(updated_at);

alter table fresh_internal.research_rate_limits enable row level security;
revoke all on table fresh_internal.research_rate_limits from public, anon, authenticated, service_role;

create or replace function public.consume_fresh_research_rate_limit(
  p_bucket_hash text,
  p_limit integer,
  p_window_seconds integer
)
returns table (allowed boolean, remaining integer, retry_after_seconds integer)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_window_started_at timestamptz;
  v_request_count integer;
begin
  if p_bucket_hash is null or p_bucket_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid rate-limit bucket';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 100
     or p_window_seconds is null or p_window_seconds < 1 or p_window_seconds > 86400 then
    raise exception 'Invalid rate-limit policy';
  end if;

  insert into fresh_internal.research_rate_limits as current_bucket (
    bucket_hash, window_started_at, request_count, updated_at
  ) values (p_bucket_hash, v_now, 1, v_now)
  on conflict (bucket_hash) do update
  set window_started_at = case
        when current_bucket.window_started_at + pg_catalog.make_interval(secs => p_window_seconds) <= v_now
          then v_now
        else current_bucket.window_started_at
      end,
      request_count = case
        when current_bucket.window_started_at + pg_catalog.make_interval(secs => p_window_seconds) <= v_now
          then 1
        else current_bucket.request_count + 1
      end,
      updated_at = v_now
  returning current_bucket.window_started_at, current_bucket.request_count
  into v_window_started_at, v_request_count;

  allowed := v_request_count <= p_limit;
  remaining := case when allowed then p_limit - v_request_count else 0 end;
  retry_after_seconds := case
    when allowed then 0
    else greatest(
      1,
      ceil(extract(epoch from (
        v_window_started_at + pg_catalog.make_interval(secs => p_window_seconds) - v_now
      )))::integer
    )
  end;
  return next;

  -- Opportunistic bounded retention cleanup; one row is retained per opaque client key.
  if pg_catalog.random() < 0.01 then
    delete from fresh_internal.research_rate_limits
    where updated_at < v_now - interval '30 days';
  end if;
end;
$function$;

revoke all on function public.consume_fresh_research_rate_limit(text, integer, integer)
  from public, anon, authenticated;
grant execute on function public.consume_fresh_research_rate_limit(text, integer, integer)
  to service_role;
